package com.tutorhub.parent.service;
import com.tutorhub.common.exception.*; import com.tutorhub.common.security.UserPrincipal; import com.tutorhub.parent.dto.*; import com.tutorhub.parent.entity.*; import com.tutorhub.parent.repository.*; import com.tutorhub.user.entity.Role; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ParentService { private final ParentProfileRepository parents; private final ChildRepository children; public ParentService(ParentProfileRepository parents,ChildRepository children){this.parents=parents;this.children=children;} @Transactional(readOnly=true) public List<ChildResponse> children(UserPrincipal p){role(p);return children.findByParentUserId(p.id()).stream().map(this::out).toList();} @Transactional public ChildResponse create(UserPrincipal p,ChildRequest r){ParentProfile parent=parent(p);Child c=new Child();c.setParent(parent);copy(c,r);return out(children.save(c));} @Transactional public ChildResponse update(UserPrincipal p,Long id,ChildRequest r){Child c=children.findByIdAndParentUserId(id,p.id()).orElseThrow(()->new NotFoundException("Child not found"));copy(c,r);return out(c);} @Transactional public void delete(UserPrincipal p,Long id){children.findByIdAndParentUserId(id,p.id()).ifPresentOrElse(children::delete,()->{throw new NotFoundException("Child not found");});} private ParentProfile parent(UserPrincipal p){role(p);return parents.findById(p.id()).orElseThrow(()->new NotFoundException("Parent profile not found"));} private void role(UserPrincipal p){if(p.role()!=Role.PARENT)throw new ForbiddenException("Parent role required");} private void copy(Child c,ChildRequest r){c.setName(r.name());c.setGrade(r.grade());c.setSchool(r.school());c.setNotes(r.notes());} private ChildResponse out(Child c){return new ChildResponse(c.getId(),c.getName(),c.getGrade(),c.getSchool(),c.getNotes());} }
